func:
    msg.topic = msg.topic;
    msg.payload = msg.payload;

return msg;

if (msg.payload === 'arm') {
    flow.set('sosArmed', true);
    flow.set('sosArmedTime', Date.now());
    node.warn('SOS armed - press Confirm SOS within 10 seconds');
    return null;
}
if (msg.payload === 'confirm') {
    if (flow.get('sosArmed')) {
        var elapsed = Date.now() - (flow.get('sosArmedTime') || 0);
        if (elapsed < 10000) {
            flow.set('sosArmed', false);
            msg.topic = 'electrical.switches.navigationLights.command.adHocSignal';
            msg.payload = 'sos';
            return msg;
        } else {
            flow.set('sosArmed', false);
            node.warn('SOS arm expired - please arm again.');
        }
    } else {
        node.warn('SOS not armed - press Arm SOS first.');
    }
}
return null;

const enabled = msg.payload === true || msg.payload === 'true' || msg.payload === 1;
const cls = enabled ? 'night-flag-on' : 'night-flag-off';

const palette = enabled
    ? { bgcolor: '#3a0000', color: '#ffd0d0' }
    : { bgcolor: '#2a2a2a', color: '#e0e0e0' };

return {
    ui_update: {
        class: cls,
        ...palette
    },
    class: cls
};
